const KEY='good-news';
function load(){return JSON.parse(localStorage.getItem(KEY)||'[]')}
function publish(text,category){const list=load();list.unshift({id:Date.now(),text,category,likes:0,at:new Date().toISOString()});localStorage.setItem(KEY,JSON.stringify(list));render()}
function like(id){const list=load();list.find(x=>x.id===id).likes++;localStorage.setItem(KEY,JSON.stringify(list));render()}
function render(){const app=document.getElementById('app');app.innerHTML=load().map(x=>`<article class=card><p>${x.text}</p><button onclick=like(${x.id})>赞 ${x.likes}</button></article>`).join('')}

